begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.classroom_lifecycle(uuid,uuid,text)','execute'),'anonymous start denied');
select ok(not has_function_privilege('authenticated','public.append_classroom_internal(uuid,uuid,text,jsonb,text,jsonb)','execute'),'internal append denied');
select ok(not has_function_privilege('authenticated','public.abandon_classroom_internal(uuid)','execute'),'internal abandon denied');
select ok(not has_function_privilege('authenticated','public.require_classroom_preview(uuid)','execute'),'authorization helper internal');
insert into auth.users(id,email_confirmed_at) values('a5000000-0000-0000-0000-000000000001',now()),('a5000000-0000-0000-0000-000000000002',now()),('a5000000-0000-0000-0000-000000000003',now()),('a5000000-0000-0000-0000-000000000004',now()),('a5000000-0000-0000-0000-000000000005',null);
insert into public.users(id,role) values('a5000000-0000-0000-0000-000000000001','PARENT'),('a5000000-0000-0000-0000-000000000002','PARENT'),('a5000000-0000-0000-0000-000000000003','STUDENT'),('a5000000-0000-0000-0000-000000000004','ADMIN'),('a5000000-0000-0000-0000-000000000005','PARENT');
insert into public.parent_profiles(user_id,display_name) values('a5000000-0000-0000-0000-000000000001','A'),('a5000000-0000-0000-0000-000000000002','B'),('a5000000-0000-0000-0000-000000000005','Unverified');
insert into public.student_profiles(id,user_id,display_name,grade) values('a5100000-0000-0000-0000-000000000001','a5000000-0000-0000-0000-000000000003','Selected',8),('a5100000-0000-0000-0000-000000000002',null,'Other',8),('a5100000-0000-0000-0000-000000000003',null,'Sibling',8);
insert into public.parent_student_relationships values('a5000000-0000-0000-0000-000000000001','a5100000-0000-0000-0000-000000000001'),('a5000000-0000-0000-0000-000000000002','a5100000-0000-0000-0000-000000000002'),('a5000000-0000-0000-0000-000000000001','a5100000-0000-0000-0000-000000000003');
insert into auth.sessions(id,user_id) values('a5200000-0000-0000-0000-000000000001','a5000000-0000-0000-0000-000000000001'),('a5200000-0000-0000-0000-000000000002','a5000000-0000-0000-0000-000000000001');
select set_config('request.jwt.claims','{"sub":"a5000000-0000-0000-0000-000000000001","session_id":"a5200000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select public.enroll_parent_student(gen_random_uuid(),'a5100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101',jsonb_build_object('schemaVersion',1,'timezone','UTC','lessonDurationMinutes',30,'weeklyFrequency',1,'slots',jsonb_build_array(jsonb_build_object('weekday',1,'time','16:00')),'earliestDate',(current_date+7)::text));
reset role;
create temp table fixture as select id,lesson_position from public.lesson_schedules where student_id='a5100000-0000-0000-0000-000000000001';
grant select on fixture to authenticated;
update public.lesson_schedules set status='cancelled' where id=(select id from fixture where lesson_position=3);
update public.lesson_schedules set starts_at=now()-interval '2 days',ends_at=now()-interval '2 days'+interval '30 minutes' where id=(select id from fixture where lesson_position=4);
set local role authenticated;
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'start')$$,'42501',null,'parent mode cannot use classroom actions');
select public.begin_student_preview('a5100000-0000-0000-0000-000000000001');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=3),gen_random_uuid(),'start')$$,'22023',null,'cancelled reservation denied');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=4),gen_random_uuid(),'start')$$,'22023',null,'past reservation denied');
select throws_ok($$select public.classroom_lifecycle(gen_random_uuid(),gen_random_uuid(),'start')$$,'42501',null,'guessed reservation denied');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'resume')$$,'22023',null,'resume before start denied');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000001','start')$$,'authorized start');
select is((select count(*)::integer from public.lessons where classroom_mode='supervised_preview'),1,'one canonical lesson');
select is((public.classroom_replay((select id from fixture where lesson_position=1),0)->'lesson'->>'status'),'active','start active');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000001','start')$$,'exact retry succeeds');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'start')$$,'duplicate starts resolve same lesson');
select is(jsonb_array_length(public.classroom_replay((select id from fixture where lesson_position=1),0)->'events'),2,'ready and started once');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000001','pause')$$,'22023',null,'request ID cannot change operation');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=2),gen_random_uuid(),'start')$$,'P5001',null,'same student conflicting room denied');
select is((select count(*)::integer from public.parent_profiles),0,'parent account stays hidden');
select is((select count(*)::integer from public.questions),0,'private answers stay hidden');
select is((select count(*)::integer from public.lesson_events),0,'raw/internal events unreadable');
select throws_ok($$insert into public.lesson_events(lesson_id,event_type) select id,'forged' from public.lessons$$,'42501',null,'direct event write denied');
select throws_ok($$update public.student_skills set mastery_score=1$$,'42501',null,'mastery write denied');
select throws_ok($$select public.update_parent_student('a5100000-0000-0000-0000-000000000001','Forbidden',8,null)$$,'42501',null,'parent mutation still denied');
select lives_ok($$select public.classroom_append((select id from fixture where lesson_position=1),'a5400000-0000-4000-8000-000000000001',0,'{"kind":"stroke","payload":{"points":[{"x":0,"y":0},{"x":1,"y":1}],"color":"#263b36","width":4}}')$$,'validated stroke persisted');
select lives_ok($$select public.classroom_append((select id from fixture where lesson_position=1),'a5400000-0000-4000-8000-000000000001',0,'{"kind":"stroke","payload":{"points":[{"x":0,"y":0},{"x":1,"y":1}],"color":"#263b36","width":4}}')$$,'duplicate command delivery idempotent');
select is(jsonb_array_length(public.classroom_replay((select id from fixture where lesson_position=1),0)->'events'),3,'one durable stroke');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),'a5400000-0000-4000-8000-000000000001',0,'{"kind":"clear_board","payload":{"confirmed":true}}')$$,'22023',null,'changed command retry denied');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"stroke","payload":{"points":[{"x":-1,"y":0},{"x":1,"y":1}],"color":"#263b36","width":4}}')$$,'22023',null,'invalid coordinates denied');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"clear_board","payload":{"confirmed":false}}')$$,'22023',null,'clear confirmation required');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"write_math","payload":{"text":"AI"}}')$$,'22023',null,'AI command spoof denied');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,jsonb_build_object('kind','stroke','payload',jsonb_build_object('points',(select jsonb_agg(jsonb_build_object('x',0,'y',0)) from generate_series(1,257)),'color','#263b36','width',4)))$$,'22023',null,'oversized stroke denied');
select lives_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"undo","payload":{"targetId":"a5400000-0000-4000-8000-000000000001"}}')$$,'undo valid target');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"undo","payload":{"targetId":"a5400000-0000-4000-8000-000000000001"}}')$$,'22023',null,'already hidden target rejected');
select lives_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"redo","payload":{"targetId":"a5400000-0000-4000-8000-000000000001"}}')$$,'redo restores target');
select lives_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"erase","payload":{"targetId":"a5400000-0000-4000-8000-000000000001"}}')$$,'eraser targets stroke');
select lives_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"clear_board","payload":{"confirmed":true}}')$$,'confirmed clear');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"redo","payload":{"targetId":"a5400000-0000-0000-000000000001"}}')$$,'22023',null,'clear invalidates undo history');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000002','pause')$$,'pause active');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000002','pause')$$,'pause retry');
select is((public.classroom_replay((select id from fixture where lesson_position=1),0)->'lesson'->>'status'),'paused','pause persists');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"connection_recovered","payload":{}}')$$,'40001',null,'drawing while paused/stale epoch denied');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000003','resume')$$,'resume paused');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000003','resume')$$,'resume retry');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),0,'{"kind":"connection_recovered","payload":{}}')$$,'40001',null,'pre-interruption command stays stale after resume');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'heartbeat')$$,'authorized reconnect heartbeat');
select lives_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),2,'{"kind":"connection_recovered","payload":{}}')$$,'operational recovery event accepted');
select is((public.classroom_replay((select id from fixture where lesson_position=1),0)->'lesson'->>'epoch')::integer,2,'pause/resume cancel earlier instructions');
select throws_ok($$select public.classroom_replay((select id from fixture where lesson_position=1),-1)$$,'22023',null,'invalid replay cursor denied');
-- Independent real Auth session cannot commandeer this active lesson.
select set_config('request.jwt.claims','{"sub":"a5000000-0000-0000-0000-000000000001","session_id":"a5200000-0000-0000-0000-000000000002"}',true);
select public.begin_student_preview('a5100000-0000-0000-0000-000000000001');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'pause')$$,'42501',null,'independent session cannot mutate current classroom');
select set_config('request.jwt.claims','{"sub":"a5000000-0000-0000-0000-000000000001","session_id":"a5200000-0000-0000-0000-000000000001"}',true);
-- Bound event rate is enforced at the database boundary.
do $$begin for i in 1..54 loop perform public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),2,'{"kind":"connection_recovered","payload":{}}'); end loop; end $$;
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),2,'{"kind":"connection_recovered","payload":{}}')$$,'P5002',null,'per-room event rate enforced');
-- Changing lifecycle commands also have a bound; end is never rate-blocked.
do $$begin for i in 1..26 loop perform public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),case when i%2=1 then 'pause' else 'resume' end); end loop; end $$;
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'pause')$$,'P5002',null,'lifecycle transition rate enforced');
-- Simulate the bounded history reaching capacity; closure must remain possible.
reset role;
update public.lessons set event_sequence=2990 where schedule_id=(select id from fixture where lesson_position=1);
set local role authenticated;
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'pause')$$,'P5003',null,'history cap reserves lifecycle closure');
select throws_ok($$select public.classroom_append((select id from fixture where lesson_position=1),gen_random_uuid(),28,'{"kind":"connection_recovered","payload":{}}')$$,'P5003',null,'history cap blocks further appends');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000004','end')$$,'end active');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),'a5300000-0000-0000-0000-000000000004','end')$$,'end retry');
select is((public.classroom_replay((select id from fixture where lesson_position=1),0)->'lesson'->>'status'),'ended','terminal ended');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'resume')$$,'22023',null,'ended cannot resume');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'start')$$,'22023',null,'ended cannot restart');
select is((select status from public.lesson_schedules where lesson_position=1 and student_id='a5100000-0000-0000-0000-000000000001'),'scheduled','preview never completes reservation');
select is((select sum(evidence_count)::integer from public.student_skills where student_id='a5100000-0000-0000-0000-000000000001'),0,'no fabricated evidence');
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=2),gen_random_uuid(),'start')$$,'another reservation after end');
reset role;
update public.lessons set last_seen_at=now()-interval '16 minutes' where schedule_id=(select id from fixture where lesson_position=2);
set local role authenticated;
select lives_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=2),gen_random_uuid(),'heartbeat')$$,'expired session reconciled');
select is((public.classroom_replay((select id from fixture where lesson_position=2),0)->'lesson'->>'status'),'abandoned','stale session explicitly abandoned');
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=2),gen_random_uuid(),'resume')$$,'22023',null,'abandoned terminal');
select public.end_student_preview();
select set_config('request.jwt.claims','{"sub":"a5000000-0000-0000-0000-000000000002","session_id":"a5200000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select public.classroom_replay((select id from fixture where lesson_position=1),0)$$,'42501',null,'cross family replay denied');
select set_config('request.jwt.claims','{"sub":"a5000000-0000-0000-0000-000000000003","session_id":"a5200000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'start')$$,'42501',null,'student cannot impersonate supervised parent');
select set_config('request.jwt.claims','{"sub":"a5000000-0000-0000-0000-000000000004","session_id":"a5200000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select public.classroom_replay((select id from fixture where lesson_position=1),0)$$,'42501',null,'admin label no classroom bypass');
reset role;
select is((select count(*)::integer from public.lessons where student_id='a5100000-0000-0000-0000-000000000001'),2,'no duplicate or partial sessions');
select is((select count(*)::integer from public.lesson_outcomes),0,'no manufactured outcomes');
select is((select count(*)::integer from public.audit_logs where actor_id='a5000000-0000-0000-0000-000000000001' and action='classroom.end'),1,'idempotent end audit');
select is((select count(*)::integer from public.lesson_events where source='system_preview' and event_type='lesson_abandoned'),1,'abandonment timeline explicit');
select throws_ok($$update public.lessons set classroom_mode='instructional',status='completed' where schedule_id=(select id from fixture where lesson_position=1)$$,'22023',null,'cannot reinterpret rehearsal as genuine attendance');
select throws_ok($$update public.lessons set curriculum_version_id=gen_random_uuid() where schedule_id=(select id from fixture where lesson_position=1)$$,'22023',null,'published pin cannot change');
select throws_ok($$update public.lesson_events set payload='{}' where id='a5400000-0000-4000-8000-000000000001'$$,'42501',null,'stored classroom event immutable');
select throws_ok($$delete from public.lesson_events where id='a5400000-0000-4000-8000-000000000001'$$,'42501',null,'stored timeline deletion denied');
select * from finish();
rollback;
